// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 depositAmount, uint256 amount, address actor) public {
        vm.assume(depositAmount <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c));
        depositAmount = bound(depositAmount, 1, 10 ether);
        amount = bound(amount, 1, depositAmount);
        vm.deal(actor, depositAmount + 1 ether);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;
        bool ok;
        vm.prank(actor);
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok || (actor.balance == callerBefore + amount && address(c).balance == contractBefore - amount));
    }
}
